 private void connect(){if(connecting)return;connecting=true;connected=false;if(browser!=null)browser.disconnect();Bundle hints=new Bundle();hints.putBoolean("android.media.browse.CONTENT_STYLE_SUPPORTED",true);
  browser=new MediaBrowser(this,new ComponentName(this,"com.amazon.mp3.auto.AutoMusicService"),new MediaBrowser.ConnectionCallback(){
   public void onConnected(){connecting=false;connected=true;controller=new MediaController(TvActivity.this,browser.getSessionToken());setMediaController(controller);TvBridge.configure(TvActivity.this);TvPlaybackService.routeSession(TvActivity.this,controller);if(pendingMedia!=null){String media=pendingMedia;pendingMedia=null;play(media,null);}else if(pendingShowPlayer){pendingShowPlayer=false;showPlayer();}else home();}
   public void onConnectionFailed(){connecting=false;welcome("Sign in to load your Amazon Music library.");}
   public void onConnectionSuspended(){connected=false;connecting=false;welcome("Connection interrupted. Select Reconnect.");}
  },hints);try{browser.connect();}catch(Exception e){connecting=false;welcome("Could not connect to Amazon Music.");}}
