 private void subscribe(String media,java.util.function.Consumer<List<MediaBrowser.MediaItem>> callback){final int token=generation;MediaBrowser.SubscriptionCallback sub=new MediaBrowser.SubscriptionCallback(){public void onChildrenLoaded(String p,List<MediaBrowser.MediaItem> list){if(token==generation)callback.accept(list==null?Collections.emptyList():list);}public void onError(String p){if(token==generation)status.setText("Could not load music. Check sign-in and network.");}};MediaBrowser.SubscriptionCallback old=subscriptions.put(media,sub);if(old!=null)browser.unsubscribe(media,old);browser.subscribe(media,sub);}
 private void home(){if(!connected){connect();return;}history.clear();load(browser.getRoot(),"Home",true);}
 private void library(){if(!connected){connect();return;}clear();subscribe(browser.getRoot(),items->{for(MediaBrowser.MediaItem i:items)if(String.valueOf(i.getDescription().getTitle()).toLowerCase(Locale.ROOT).matches(".*(library|my music).*")){load(i.getMediaId(),"Library",true);return;}load(browser.getRoot(),"Library",true);});}
 private void load(String media,String label,boolean shelves){
  if(!connected){connect();return;}clear();parent=media;title=label;page="browse";ScrollView sc=new ScrollView(this);sc.setClipChildren(false);body=new LinearLayout(this);body.setOrientation(1);body.setClipChildren(false);body.setPadding(0,dp(8),0,dp(16));sc.setVerticalScrollBarEnabled(false);sc.addView(body);content.addView(sc,new ViewGroup.LayoutParams(-1,-1));if(status.getParent()!=null)((ViewGroup)status.getParent()).removeView(status);body.addView(status);status.setVisibility(View.VISIBLE);status.setText("Loading...");
  subscribe(media,items->{status.setText("");status.setVisibility(View.GONE);if(items.isEmpty()){welcome("Sign in, then return here and select Home.");return;}boolean tracks=true;for(MediaBrowser.MediaItem i:items)if(i.isBrowsable())tracks=false;if(tracks){trackRows(items);return;}
   if(shelves){int count=0;ArrayList<MediaBrowser.MediaItem> playable=new ArrayList<>();for(MediaBrowser.MediaItem i:items){if(!i.isBrowsable()){playable.add(i);continue;}if(count++>=8)continue;LinearLayout row=shelf(String.valueOf(i.getDescription().getTitle()));subscribe(i.getMediaId(),children->{row.removeAllViews();renderCards(row,children.subList(0,Math.min(12,children.size())),()->{if(children.size()>12)action(row,"See all",()->navigate(i));});});}if(!playable.isEmpty()){LinearLayout row=shelf("Listen now");for(MediaBrowser.MediaItem i:playable)card(row,i);}}
   else for(int start=0;start<items.size();start+=5){LinearLayout row=shelf(start==0?label:"");for(MediaBrowser.MediaItem i:items.subList(start,Math.min(start+5,items.size())))card(row,i);}
  });
 }
