 private void navigate(MediaBrowser.MediaItem item){MediaDescription d=item.getDescription();if(item.isBrowsable()){history.push(new String[]{parent,title});load(item.getMediaId(),String.valueOf(d.getTitle()),false);}else play(item.getMediaId(),d.getExtras());}
 private void openCard(MediaBrowser.MediaItem item){
  if(item.isBrowsable()){navigate(item);return;}
  final int token=generation;final String media=item.getMediaId(),label=String.valueOf(item.getDescription().getTitle());
  MediaBrowser.SubscriptionCallback probe=new MediaBrowser.SubscriptionCallback(){
   private void finish(){try{browser.unsubscribe(media,this);}catch(Exception ignored){}}
   @Override public void onChildrenLoaded(String id,List<MediaBrowser.MediaItem> children){finish();if(token!=generation)return;if(children!=null&&!children.isEmpty()){history.push(new String[]{parent,title});load(media,label,false);}else cardDetails(item);}
   @Override public void onError(String id){finish();if(token==generation)cardDetails(item);}
  };
  try{browser.subscribe(media,probe);}catch(Exception e){cardDetails(item);}
 }
