 private void performSearch(String query){if(query==null||query.trim().isEmpty())return;String q=query.trim();suppressAutoPip=true;try{Intent in=new Intent(Intent.ACTION_VIEW,Uri.parse("https://music.amazon.ca/search/"+Uri.encode(q)));in.setClassName(this,"com.amazon.mp3.navigation.DeeplinkHandlerActivity");in.addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(in);}catch(Exception first){try{Intent in=new Intent(Intent.ACTION_SEARCH);in.setClassName(this,"com.amazon.mp3.activity.ExternalLauncherActivity");in.putExtra(android.app.SearchManager.QUERY,q);in.addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(in);}catch(Exception second){toast("Amazon search could not open");}}}
