 private void updateLyrics(MediaMetadata metadata){
  if(lyricsBody==null)return;String asin="";try{asin=TvAmazon.currentAsin();}catch(Exception ignored){}if(asin.isEmpty())asin=TvAmazon.asin(metadata.getDescription());
  if(asin.isEmpty()){if(lyricsBody.getChildCount()==0)lyricsBody.addView(text("Amazon has not exposed a song identifier for lyrics.",20));return;}
  if(!asin.equals(lyricsAsin)){lyricsAsin=asin;lyricsLines=Collections.emptyList();lyricsActive=-1;lyricsBody.removeAllViews();lyricsBody.addView(text(String.valueOf(metadata.getDescription().getTitle()),20));TextView state=text("Loading lyrics from Amazon...",22);lyricsBody.addView(state);final int token=++lyricsGeneration;final String song=asin;
   work.execute(()->{try{List<TvAmazon.Line> lines=TvAmazon.lyrics(getApplicationContext(),song);runOnUiThread(()->{if(token!=lyricsGeneration||lyricsBody==null||isDestroyed())return;lyricsLines=lines;state.setText(lines.isEmpty()?"Lyrics are unavailable for this song.":"");if(!lines.isEmpty())state.setVisibility(View.GONE);for(TvAmazon.Line line:lines){TextView t=text(line.text,line.start<0?16:31);t.setGravity(Gravity.CENTER);t.setTextColor(0xff9cacb0);t.setPadding(dp(12),dp(13),dp(12),dp(13));if(line.start>=0){focus(t,false);t.setContentDescription(line.text);t.setOnClickListener(x->{if(controller!=null)controller.getTransportControls().seekTo(line.start);});}lyricsBody.addView(t,new LinearLayout.LayoutParams(-1,-2));}highlightLyrics();});}catch(Exception e){runOnUiThread(()->{if(token==lyricsGeneration&&lyricsBody!=null)state.setText("Amazon could not load lyrics for this song. Try Reload.");});}});
  }else highlightLyrics();
 }
 private void highlightLyrics(){if(lyricsBody==null||controller==null)return;PlaybackState state=controller.getPlaybackState();if(state==null)return;long position=state.getPosition();if(state.getState()==PlaybackState.STATE_PLAYING)position+=(long)((SystemClock.elapsedRealtime()-state.getLastPositionUpdateTime())*state.getPlaybackSpeed());int active=-1;for(int i=0;i<lyricsLines.size();i++){TvAmazon.Line line=lyricsLines.get(i);if(line.start>=0&&position>=line.start&&(line.end<0||position<line.end))active=i;}if(active==lyricsActive)return;lyricsActive=active;for(int i=0;i<lyricsLines.size();i++){TextView t=(TextView)lyricsBody.getChildAt(i+2);if(t!=null)t.setTextColor(i==active?0xff42eee1:0xff9cacb0);}if(active>=0&&!lyricsBody.hasFocus()){View line=lyricsBody.getChildAt(active+2);if(line!=null)lyricsScroll.smoothScrollTo(0,Math.max(0,line.getTop()-lyricsScroll.getHeight()/3));}}

